void:
struct S{n:i64}
recursive fn set(p:S,out:i64&){p.n=9;out=p.n;}
fn main(){var s:S=S{n:2};var out:i64=0;set(s,out);assert(out==9);assert(s.n==2);print("void");}

always_return:
struct S{n:i64}
recursive fn effect()->i64{print("effect");return 1;}
recursive fn use(p:S,x:i64)->i64{return p.n+x;}
recursive fn run()->i64{return use(S{n:effect()},{return 7;8});}
fn main(){assert(run()==7);print("always_return");}

dynamic_base:
struct S{n:i64}
recursive fn read(p:S)->i64{var a:i64[]=[p.n];print("inside");return a[0];}
fn main(){var s:S=S{n:1};assert(read(s)==1);{var live:i64[]=[9];assert(read(s)==1);assert(live[0]==9);}print("dynamic_base");}
